    /// <summary>
    /// Find the mark for a credential's name. "https://github.com/asser", "GitHub" and
    /// "github.com" all land on the same one.
    /// </summary>
    public static Mark? For(string? name)
    {
        var key = Token(name);
        return key.Length > 0 && Known.TryGetValue(key, out var mark) ? mark : null;
    }

    /// <summary>The bit of a name worth matching on: no scheme, no www, no path, no TLD.</summary>
    internal static string Token(string? name)
    {
        if (string.IsNullOrWhiteSpace(name)) return "";

        var text = name.Trim().ToLowerInvariant();
        if (text.StartsWith("http://")) text = text[7..];
        if (text.StartsWith("https://")) text = text[8..];
        if (text.StartsWith("www.")) text = text[4..];

        var slash = text.IndexOf('/');
        if (slash >= 0) text = text[..slash];

        var dot = text.IndexOf('.');
        if (dot > 0) text = text[..dot];

        return new string(text.Where(char.IsLetterOrDigit).ToArray());
    }
